// lookup demo — A stitch in time saves nine (jahdb demo program)
var DATA={"A stitch in time saves nine":"Small repairs prevent big disasters."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("Small repairs prevent big disasters."));

